    async def create_creator_qualification_meeting(
        *,
        creator: Dict[str, Any],
        source: str,
    ) -> Dict[str, Any]:
        mid = f"meeting-{uuid.uuid4().hex[:10]}"
        questions = QUALIFICATION_QUESTION_SETS["creator"]
